// AlphaAI trending -> Discord rich embeds.
// One message per run: a header line + up to 10 embed "cards", each linking to
// the article page on alphai.io and showing the enriched sentiment / impact.
// Dedupes by uid across runs; anything that doesn't fit stays unmarked and
// posts on the next run. One POST per run -> no Discord rate limit.

function slugify(text) {
  return (text || '').toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}
function dateForUrl(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) { return ''; }
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${m}-${day}`;
}
function trunc(s, n) {
  s = (s == null ? '' : String(s));
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
}

const SITE = 'https://alphai.io';
const COLORS = { positive: 3066993, negative: 15158332, neutral: 9807270 };

const incoming = $input.all();
let articles = [];
for (const it of incoming) {
  const j = it.json;
  if (Array.isArray(j)) { articles = articles.concat(j); }
  else if (j && Array.isArray(j.results)) { articles = articles.concat(j.results); }
  else if (j) { articles.push(j); }
}

const store = $getWorkflowStaticData('global');
store.postedUids = store.postedUids || [];
const seen = new Set(store.postedUids);

const embeds = [];
const postedUids = [];
let budget = 0; // approx total chars across embeds (Discord hard cap is 6000)

for (const a of articles) {
  if (embeds.length >= 10) { break; }
  const enr = (a && a.enrichment) || {};
  const org = (a && a.original) || {};
  const uid = org.uid;
  const score = enr.relevance_score || 0;
  const tickers = enr.tickers || [];
  if (!uid || seen.has(uid)) { continue; }
  if (score < 8 || tickers.length === 0) { continue; }

  const insights = enr.ai_trading_insights || {};
  const ta = (insights.ticker_analysis || [])[0] || {};
  const ia = ta.impact_analysis || {};
  const ntv = insights.news_trading_value || {};
  const sentiment = ia.sentiment || 'neutral';

  const url = `${SITE}/news/article/${dateForUrl(org.time_published)}/${uid}/${slugify(org.title)}`;

  const fields = [];
  if (ia.sentiment) { fields.push({ name: 'Sentiment', value: trunc(ia.sentiment, 60), inline: true }); }
  if (ia.confidence) { fields.push({ name: 'Confidence', value: trunc(ia.confidence, 60), inline: true }); }
  if (ntv.actionability_score) { fields.push({ name: 'Actionability', value: trunc(ntv.actionability_score, 60), inline: true }); }
  if (ia.price_impact_prediction) { fields.push({ name: 'Likely price impact', value: trunc(ia.price_impact_prediction, 300), inline: false }); }

  const embed = {
    title: trunc(`[${score}] ${tickers.join(', ')} — ${org.title || ''}`, 250),
    url,
    description: trunc(org.summary || ia.summary || '', 300),
    color: COLORS[sentiment] || COLORS.neutral,
    fields,
    footer: { text: trunc(`${enr.category || 'news'} · ${org.source || org.source_domain || 'source'} · via AlphaAI`, 120) },
  };
  if (org.time_published) { embed.timestamp = org.time_published; }

  const size = JSON.stringify(embed).length;
  if (budget + size > 5200 && embeds.length > 0) { break; }
  budget += size;

  embeds.push(embed);
  postedUids.push(uid);
  seen.add(uid);
}

if (embeds.length === 0) { return []; }

for (const uid of postedUids) { store.postedUids.push(uid); }
if (store.postedUids.length > 500) { store.postedUids = store.postedUids.slice(-500); }

const n = embeds.length;
const content = `📈 **AlphaAI — ${n} new top ${n === 1 ? 'story' : 'stories'}**`;

return [{ json: { payload: { content, embeds } } }];
